{
  "id": "open_logan_paul_youtube_channel",
  "name": "Open Logan Paul's YouTube Channel",
  "type": "sequential",
  "steps": [
    {
      "tool": "web_search",
      "args": {
        "query": "Logan Paul official YouTube channel"
      },
      "store_result_as": "$results"
    },
    {
      "tool": "llm_transform",
      "args": {
        "prompt": "Return the URL of Logan Paul's official YouTube channel as plain text, nothing else.",
        "context": "$results"
      },
      "store_result_as": "$channel_url"
    },
    {
      "tool": "fetch_page",
      "args": {
        "url": "$channel_url"
      },
      "store_result_as": "$page"
    },
    {
      "tool": "file_write",
      "args": {
        "path": "/tmp/logan_channel_verify.txt",
        "content": "$page.content"
      },
      "store_result_as": "$tmp"
    },
    {
      "tool": "file_read",
      "args": {
        "path": "/tmp/logan_channel_verify.txt",
        "start_line": 1,
        "end_line": 50
      },
      "store_result_as": "$preview"
    },
    {
      "tool": "llm_transform",
      "args": {
        "prompt": "Does this page content show a real YouTube channel or a 'not available' / 'error' page? Reply with just: yes or no.",
        "context": "$preview"
      },
      "store_result_as": "$verdict"
    },
    {
      "type": "conditional",
      "condition": {
        "field": "$verdict",
        "operator": "contains",
        "value": "yes"
      },
      "if_true": {
        "tool": "app_open",
        "args": {
          "target": "$channel_url"
        }
      },
      "if_false": {
        "type": "sequential",
        "steps": [
          {
            "tool": "web_search",
            "args": {
              "query": "Logan Paul YouTube channel site:youtube.com"
            },
            "store_result_as": "$retry"
          },
          {
            "tool": "llm_transform",
            "args": {
              "prompt": "Return only the channel URL.",
              "context": "$retry"
            },
            "store_result_as": "$final_url"
          },
          {
            "tool": "app_open",
            "args": {
              "target": "$final_url"
            }
          }
        ]
      }
    }
  ]
}

